+  private static int countCoinsDP(int[] coins, int targetSum) {
+    int numCoins = coins.length;
+    int[][] dp = new int[numCoins + 1][targetSum + 1];
+
+    dp[0][0] = 1;
+
+    for (int i = 1; i <= numCoins; i++) {
